$T$ is the point of contact where tangent $TP$ touches the circle, centre $O$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc}
\coordinate (O) at (0,0);
\coordinate (T) at (0,2.4);
\coordinate (P) at (2.665,2.4);
\draw (O) circle (2.4);
\fill (O) circle (1.5pt);
\node[below left] at (O) {$O$};
\draw (O) -- (T) -- (P) -- (O);
\node[above left] at (T) {$T$};
\node[right] at (P) {$P$};
\coordinate (ta) at ($(T)!0.3cm!(O)$);
\coordinate (tp) at ($(T)!0.3cm!(P)$);
\draw (ta) -- ($(ta)+(tp)-(T)$) -- (tp);
\pic[draw, "$48^{\circ}$", angle radius=0.6cm, angle eccentricity=2] {angle=P--O--T};
\pic[draw, "$x$", angle radius=0.5cm, angle eccentricity=2] {angle=T--P--O};
\end{tikzpicture}
[/tikz]
Find the value of $x$.

$PT$ and $PQ$ are tangents to the circle, centre $O$, from the external point $P$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc, decorations.markings}
\tikzset{tickmark/.style={postaction={decorate, decoration={markings, mark=at position 0.5 with {\draw[black] (0pt,-4pt) -- (0pt,4pt);}}}}}
\coordinate (O) at (0,0);
\coordinate (P) at (5,0);
\coordinate (T1) at (1.8,2.4);
\coordinate (T2) at (1.8,-2.4);
\draw (O) circle (3);
\fill (O) circle (1.5pt);
\node[left] at (O) {$O$};
\draw (O) -- (T1);
\draw (O) -- (T2);
\draw[tickmark] (P) -- (T1) node[midway, above left] {$4\text{ cm}$};
\draw[tickmark] (P) -- (T2);
\node[above] at (T1) {$T$};
\node[below] at (T2) {$Q$};
\node[right] at (P) {$P$};
\coordinate (t1o) at ($(T1)!0.25cm!(O)$);
\coordinate (t1p) at ($(T1)!0.25cm!(P)$);
\draw (t1o) -- ($(t1o)+(t1p)-(T1)$) -- (t1p);
\coordinate (t2o) at ($(T2)!0.25cm!(O)$);
\coordinate (t2p) at ($(T2)!0.25cm!(P)$);
\draw (t2o) -- ($(t2o)+(t2p)-(T2)$) -- (t2p);
\end{tikzpicture}
[/tikz]
If $PT = 4\text{ cm}$, find the length of $PQ$.

$PT$ and $PQ$ are tangents to the circle, centre $O$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc}
\coordinate (P) at (0,0);
\coordinate (O) at (3.655,0);
\coordinate (T1) at (2.145,1.8);
\coordinate (T2) at (2.145,-1.8);
\draw (O) circle (2.349);
\fill (O) circle (1.5pt);
\node[right] at (O) {$O$};
\draw (O) -- (T1);
\draw (O) -- (T2);
\draw (P) -- (T1);
\draw (P) -- (T2);
\draw (T1) -- (T2);
\node[above] at (T1) {$T$};
\node[below] at (T2) {$Q$};
\node[left] at (P) {$P$};
\coordinate (t1o) at ($(T1)!0.25cm!(O)$);
\coordinate (t1p) at ($(T1)!0.25cm!(P)$);
\draw (t1o) -- ($(t1o)+(t1p)-(T1)$) -- (t1p);
\coordinate (t2o) at ($(T2)!0.25cm!(O)$);
\coordinate (t2p) at ($(T2)!0.25cm!(P)$);
\draw (t2o) -- ($(t2o)+(t2p)-(T2)$) -- (t2p);
\pic[draw, "$80^{\circ}$", angle radius=0.6cm, angle eccentricity=2] {angle=T2--P--T1};
\pic[draw, "$x$", angle radius=0.5cm, angle eccentricity=2] {angle=P--T1--T2};
\end{tikzpicture}
[/tikz]
Find the value of $x$.

$T$ is the point of contact of tangent $TP$ to the circle, centre $O$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc}
\coordinate (O) at (0,0);
\coordinate (T) at (0,6);
\coordinate (P) at (8,6);
\draw (O) circle (6);
\fill (O) circle (1.5pt);
\node[below left] at (O) {$O$};
\draw (O) -- (T) node[midway, left] {$6\text{ cm}$};
\draw (T) -- (P) node[midway, above] {$8\text{ cm}$};
\draw (O) -- (P) node[midway, below right] {$x$};
\node[above left] at (T) {$T$};
\node[right] at (P) {$P$};
\coordinate (ta) at ($(T)!0.3cm!(O)$);
\coordinate (tp) at ($(T)!0.3cm!(P)$);
\draw (ta) -- ($(ta)+(tp)-(T)$) -- (tp);
\end{tikzpicture}
[/tikz]
Find the length of $x$.

$PT$ and $PQ$ are tangents to the circle, centre $O$, and $\angle TOQ = 112^{\circ}$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=0.42]
\usetikzlibrary{calc, decorations.markings}
\tikzset{tickmark/.style={postaction={decorate, decoration={markings, mark=at position 0.5 with {\draw[black] (0pt,-4pt) -- (0pt,4pt);}}}}}
\coordinate (O) at (0,0);
\coordinate (P) at (8.941,0);
\coordinate (T1) at (2.796,4.145);
\coordinate (T2) at (2.796,-4.145);
\draw (O) circle (5);
\fill (O) circle (1.5pt);
\node[left] at (O) {$O$};
\draw (O) -- (T1);
\draw (O) -- (T2);
\draw (P) -- (T1);
\draw (P) -- (T2);
\node[above] at (T1) {$T$};
\node[below] at (T2) {$Q$};
\node[right] at (P) {$P$};
\coordinate (t1o) at ($(T1)!0.25cm!(O)$);
\coordinate (t1p) at ($(T1)!0.25cm!(P)$);
\draw (t1o) -- ($(t1o)+(t1p)-(T1)$) -- (t1p);
\coordinate (t2o) at ($(T2)!0.25cm!(O)$);
\coordinate (t2p) at ($(T2)!0.25cm!(P)$);
\draw (t2o) -- ($(t2o)+(t2p)-(T2)$) -- (t2p);
\pic[draw, "$112^{\circ}$", angle radius=0.6cm, angle eccentricity=2] {angle=T2--O--T1};
\end{tikzpicture}
[/tikz]
Find $\angle TPQ$.
